:root{
  --bg:#0f1220;
  --card:#171a2b;
  --ink:#eef0ff;
  --muted:#b9bddb;
  --faint:#8b90b3;
  --accent:#7dd3fc;
  --accent2:#a78bfa;
  --good:#34d399;
  --bad:#fb7185;
  --line:rgba(255,255,255,.10);
}
*{box-sizing:border-box}
body{
  margin:0;
  font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Arial, "Noto Sans", "Liberation Sans", sans-serif;
  background: radial-gradient(1200px 700px at 20% 0%, rgba(167,139,250,.18), transparent 55%),
              radial-gradient(900px 600px at 90% 10%, rgba(125,211,252,.16), transparent 50%),
              var(--bg);
  color:var(--ink);
}
.wrap{max-width:980px;margin:0 auto;padding:22px 16px 40px}
header{padding:8px 4px 14px}
h1{margin:0 0 6px;font-size:28px;letter-spacing:.2px}
.sub{margin:0;color:var(--muted);line-height:1.35}
.card{
  background: linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02));
  border:1px solid var(--line);
  border-radius:14px;
  padding:16px;
  margin:14px 0;
  box-shadow: 0 10px 30px rgba(0,0,0,.25);
}
.card h2{margin:0 0 8px;font-size:18px}
.help{margin:0 0 12px;color:var(--muted);line-height:1.35}
.ex{padding:1px 6px;border:1px solid var(--line);border-radius:999px;color:var(--ink);background:rgba(255,255,255,.03)}
.row{display:flex;gap:12px;align-items:center;margin:10px 0}
.row.two{align-items:end}
.row>label{width:170px;color:var(--muted);font-size:13px}
input[type=text], select{
  width:100%;
  padding:10px 12px;
  border-radius:10px;
  border:1px solid var(--line);
  background:rgba(0,0,0,.25);
  color:var(--ink);
  outline:none;
}
input[type=text]:focus, select:focus{border-color:rgba(125,211,252,.55);box-shadow:0 0 0 3px rgba(125,211,252,.12)}
.modes{display:flex;flex-wrap:wrap;gap:8px}
.chip{
  display:inline-flex;align-items:center;gap:8px;
  padding:8px 10px;border-radius:999px;
  border:1px solid var(--line);
  background:rgba(255,255,255,.03);
  color:var(--ink);
  font-size:13px;
  user-select:none;
}
.chip input{accent-color: var(--accent)}
.buttons{display:flex;flex-wrap:wrap;gap:10px;margin-top:12px}
button{
  border:1px solid rgba(255,255,255,.14);
  background: linear-gradient(180deg, rgba(125,211,252,.22), rgba(125,211,252,.10));
  color:var(--ink);
  padding:10px 12px;
  border-radius:12px;
  cursor:pointer;
  font-weight:650;
}
button:hover{filter:brightness(1.05)}
button:active{transform:translateY(1px)}
button.ghost{
  background:rgba(255,255,255,.03);
  font-weight:600;
}
.out{
  margin-top:14px;
  border-top:1px dashed var(--line);
  padding-top:12px;
}
.line{display:flex;gap:10px;align-items:baseline;margin:6px 0}
.k{width:150px;color:var(--faint);font-size:12px;text-transform:uppercase;letter-spacing:.08em}
.v{color:var(--ink)}
.v.big{font-size:22px;letter-spacing:.2px}
.small{color:var(--muted);font-size:13px;line-height:1.35}
.bank{display:flex;flex-wrap:wrap;gap:10px;margin:10px 0 6px}
.word{
  padding:8px 10px;
  border-radius:999px;
  border:1px solid var(--line);
  background:rgba(0,0,0,.18);
  cursor:pointer;
  user-select:none;
  transition: transform .05s ease, border-color .15s ease, background .15s ease;
}
.word:hover{border-color:rgba(167,139,250,.45)}
.word.sel{border-color:rgba(125,211,252,.65);background:rgba(125,211,252,.10)}
.word.good{border-color:rgba(52,211,153,.7);background:rgba(52,211,153,.10)}
.word.bad{border-color:rgba(251,113,133,.7);background:rgba(251,113,133,.10)}
.score{margin-top:8px;color:var(--muted)}
footer{padding:6px 4px 0}
.fine{margin:0;color:var(--faint);font-size:12px;line-height:1.35}
@media (max-width:720px){
  .row{flex-direction:column;align-items:stretch}
  .row>label{width:auto}
  .k{width:120px}
}

