const $ = (sel) => document.querySelector(sel);
const $$ = (sel) => Array.from(document.querySelectorAll(sel));

// --- Greek helpers (intentionally lightweight) ---
const COMBINING = /[\u0300-\u036f]/g; // combining diacritics

function nfd(s){ return (s||"").normalize('NFD'); }
function nfc(s){ return (s||"").normalize('NFC'); }

function stripCombining(s){ return nfd(s).replace(COMBINING, ''); }

// Remove accents/breathings etc. but keep base letters.
function stripDiacritics(s){
  return stripCombining(s)
    .replace(/\u0345/g,'') // iota subscript (combining ypogegrammeni)
    .replace(/\u037A/g,'');
}

function lastIndexOfGreekVowelBase(s){
  // Find last vowel letter (base) in a string (NFD, diacritics stripped).
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω','ά','έ','ή','ί','ό','ύ','ώ','Ά','Έ','Ή','Ί','Ό','Ύ','Ώ']);
  for(let i=s.length-1;i>=0;i--){
    const ch = s[i];
    if(vowels.has(ch)) return i;
  }
  return -1;
}

function applyAcuteToVowelChar(ch, style){
  // style: 'poly' or 'mono' (both use tonos/oxia in modern Unicode precomposed where possible)
  // We map base vowel to precomposed tonos form.
  const map = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
  };
  // If already accented, keep.
  if(Object.values(map).includes(ch)) return ch;
  return map[ch] || ch;
}

function normalizeForDisplay(s){
  return nfc(s.trim().replace(/\s+/g,' '));
}

function detectEnding(sBare){
  // sBare should be diacritics-stripped but case preserved.
  const s = sBare;
  const lower = s.toLowerCase();
  if(lower.endsWith('αν')) return '-αν';
  if(lower.endsWith('ην')) return '-ην';
  if(lower.endsWith('αν ')) return '-αν';
  return '—';
}

function accentRuleAn(word, style){
  // Put acute on the last vowel before final nu if ends with -αν.
  const w0 = normalizeForDisplay(word);
  if(!w0) return {ok:false, out:'—', why:'Empty input.'};

  // Work on a diacritics-stripped version for locating letters, but apply to original-ish.
  const bare = stripDiacritics(w0);
  const lowerBare = bare.toLowerCase();
  if(!lowerBare.endsWith('αν')){
    return {ok:false, out:w0, why:"Doesn't end in -αν (after stripping diacritics)."};
  }

  // Find the vowel to accent: last vowel in the stem (i.e., before the final ν).
  // We'll operate on bare string indices.
  const stem = bare.slice(0, bare.length-1); // keep final α, remove ν? Actually -αν: last char ν; stem includes ...α
  const idx = lastIndexOfGreekVowelBase(stem);
  if(idx < 0) return {ok:false, out:w0, why:'No vowel found to accent.'};

  // Now build output based on bare, then reattach any original diacritics are ignored (toy).
  let chars = bare.split('');
  chars[idx] = applyAcuteToVowelChar(chars[idx], style);
  const out = nfc(chars.join(''));
  return {ok:true, out, why:'Applied acute to the last vowel before final ν.'};
}

function compareWithBaseAn(wordAn, baseEn){
  // Very playful: if base ends with -ην, suggest -αν form and show accent shift.
  const an = normalizeForDisplay(wordAn);
  const base = normalizeForDisplay(baseEn);
  const baseBare = stripDiacritics(base);
  const baseLower = baseBare.toLowerCase();

  let msg = [];
  if(!an && !base) return {out:'—', note:'Type something in either box.'};

  if(base && baseLower.endsWith('ην')){
    const suggestedBare = stripDiacritics(base).slice(0, -2) + 'αν';
    const suggested = accentRuleAn(suggestedBare, $('#dial').value).out;
    msg.push(`Base -ην: ${base}`);
    msg.push(`Toy “-ην → -αν” swap: ${suggested}`);
    msg.push('Herodian’s point: if it is a simple -αν nominative (not a changed form), it wants an acute.');
    return {out: msg.join('  •  '), note:'This is a playful comparison, not a real derivation engine.'};
  }

  if(an){
    const r = accentRuleAn(an, $('#dial').value);
    msg.push(`Input: ${an}`);
    msg.push(`Rule output: ${r.out}`);
    if(base) msg.push(`(Base given: ${base})`);
    return {out: msg.join('  •  '), note:'Give a base in -ην (e.g. Ἀζήν) to see the swap.'};
  }

  return {out:'—', note:'Give a base in -ην (e.g. Ἀζήν) or an -αν word.'};
}

// --- UI wiring ---
const examples = [
  'Παιαν','Παιάν','Ἰαν','Δωριαν','Ἀλκμαν','τιταν','πελεκαν','Ἀθαμαν','Ἀζαν','Ἀγριαν',
  'Αζαν','Αγριαν','Δωριάν','τιτάν','πελεκάν'
];

function currentMode(){
  return ($$('input[name="mode"]').find(r=>r.checked)||{value:'rule'}).value;
}

function run(){
  const inp = $('#inp').value;
  const base = $('#base').value;
  const style = $('#dial').value;

  const norm = normalizeForDisplay(inp);
  $('#norm').textContent = norm || '—';

  const ending = detectEnding(stripDiacritics(norm));
  $('#ending').textContent = ending;

  const mode = currentMode();
  if(mode === 'rule'){
    const r = accentRuleAn(norm, style);
    $('#out').textContent = r.out;
    $('#note').textContent = r.ok ? r.why : ('Note: ' + r.why + ' Try an -αν word.');
  } else {
    const r = compareWithBaseAn(norm, base);
    $('#out').textContent = r.out;
    $('#note').textContent = r.note;
  }
}

$('#go').addEventListener('click', run);
$('#inp').addEventListener('keydown', (e)=>{ if(e.key==='Enter') run(); });
$('#base').addEventListener('keydown', (e)=>{ if(e.key==='Enter') run(); });
$('#dial').addEventListener('change', run);
$$('input[name="mode"]').forEach(r=>r.addEventListener('change', run));

$('#rand').addEventListener('click', ()=>{
  const w = examples[Math.floor(Math.random()*examples.length)];
  $('#inp').value = w;
  run();
});

$('#clear').addEventListener('click', ()=>{
  $('#inp').value='';
  $('#base').value='';
  $('#norm').textContent='—';
  $('#ending').textContent='—';
  $('#out').textContent='—';
  $('#note').textContent='Tip: this toy is intentionally simple: it just tries to put an acute on the last vowel before final ν in -αν.';
});

// --- Mini-game ---
const bankEl = $('#wordbank');
const scoreEl = $('#score');

const gamePool = [
  // -αν candidates (some from passage, some plausible)
  'Παιάν','Ἰάν','Δωριάν','Ἀλκμάν','τιτάν','πελεκάν','Ἀθαμάν','Ἀζάν','Ἀγριάν',
  // distractors
  'Ἀζήν','Ἀθηνᾶ','Παιωνία','Γαλάτας','Πισίδας','Τλωεῖς','κῦδος','δόρατος','Ἀρκάδος','Θετταλίας'
];

function isAnWord(w){
  const bare = stripDiacritics(normalizeForDisplay(w)).toLowerCase();
  return bare.endsWith('αν');
}

function newRound(){
  bankEl.innerHTML='';
  scoreEl.textContent='Select the -αν-looking words, then Check.';

  // pick 10 random unique
  const shuffled = [...gamePool].sort(()=>Math.random()-0.5);
  const pick = shuffled.slice(0, 10);

  pick.forEach(w=>{
    const b = document.createElement('button');
    b.type='button';
    b.className='word';
    b.textContent=w;
    b.dataset.word=w;
    b.dataset.sel='0';
    b.addEventListener('click', ()=>{
      const sel = b.dataset.sel === '1';
      b.dataset.sel = sel ? '0' : '1';
      b.classList.toggle('sel', !sel);
    });
    bankEl.appendChild(b);
  });
}

$('#check').addEventListener('click', ()=>{
  const buttons = $$('#wordbank .word');
  let correct=0, total=0, picked=0;

  buttons.forEach(b=>{
    const w = b.dataset.word;
    const truth = isAnWord(w);
    const sel = b.dataset.sel === '1';
    if(sel) picked++;
    if(truth) total++;

    b.classList.remove('good','bad');
    if(sel && truth){ b.classList.add('good'); correct++; }
    else if(sel && !truth){ b.classList.add('bad'); }
    else if(!sel && truth){ /* missed */ }
  });

  scoreEl.textContent = `You picked ${picked}. Correct picks: ${correct}/${total} true -αν words in this round.`;
});

$('#reset').addEventListener('click', newRound);

// init
newRound();
run();

