function normalizeForDisplay(s){
  return nfc(s.trim().replace(/\s+/g,' '));
}

function detectEnding(sBare){
  // sBare should be diacritics-stripped but case preserved.
  const s = sBare;
  const lower = s.toLowerCase();
  if(lower.endsWith('αν')) return '-αν';
  if(lower.endsWith('ην')) return '-ην';
  if(lower.endsWith('αν ')) return '-αν';
  return '—';
}

